}

.alert-header {
  display: flex;
  justify-content: space-between;
  font-size: 0.8rem;
  font-weight: 700;
  color: #6b7280;
  margin-bottom: 0.25rem;
}

.alert-title {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.alert-msg {
  font-size: 0.95rem;
  color: #4b5563;
}

/* Stored Notifications */
.stored-container {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.batch-actions {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.notifications-list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-height: 400px;
  overflow-y: auto;
}

.notification-item {
  display: flex;
  gap: 1rem;
  padding: 1rem;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  background-color: #ffffff;
  transition: background-color 0.15s ease-in-out;
}

.notification-item.unread {
  background-color: #f0fdf4;
  border-color: #bbf7d0;
}

.notification-checkbox-container {
  display: flex;
  align-items: center;
}

.notification-checkbox-container input[type="checkbox"] {
  width: 1.1rem;
  height: 1.1rem;
  cursor: pointer;
}

.notification-content {
  flex: 1;
}

.notification-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.25rem;
}

.notification-type {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  background-color: #e5e7eb;
  padding: 0.2rem 0.5rem;
  border-radius: 4px;
}

.unread .notification-type {
  background-color: #dcfce7;
  color: #15803d;
}

.notification-status {
  font-size: 0.8rem;
  font-weight: 600;
}

.unread .notification-status {
  color: #15803d;
}

.notification-title {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

.notification-message {
  font-size: 0.95rem;
  color: #4b5563;
}

.no-data {
  text-align: center;
  color: #6b7280;
  padding: 2rem;
  font-style: italic;
}
